DO $$
DECLARE
  badge text := 'data:image/png;base64,';
BEGIN
  UPDATE public.articles
  SET formatted_content = replace(formatted_content, 'https://licensebuttons.net/l/by/4.0/88x31.png', badge)
  WHERE formatted_content LIKE '%licensebuttons.net%';

  UPDATE public.articles
  SET author_revision_html = replace(author_revision_html, 'https://licensebuttons.net/l/by/4.0/88x31.png', badge)
  WHERE author_revision_html LIKE '%licensebuttons.net%';
END $$;